begin;
create temporary table commercial_fixtures(kind text primary key,id uuid default gen_random_uuid());
insert into commercial_fixtures(kind) values('admin'),('person'),('outside'),('director'),('store'),('otherstore');
grant select on commercial_fixtures to authenticated;
insert into auth.users(id,email) select id,id||'@example.invalid' from commercial_fixtures where kind in ('admin','person','outside','director');
insert into public.eo_profiles(id,display_name,role) select id,'Teste comercial',case when kind='admin' then 'admin' when kind='director' then 'diretor' else 'gerente' end from commercial_fixtures where kind in ('admin','person','outside','director');
insert into public.eo_stores(id,code,name,region) select id,left(id::text,20),'Loja teste comercial',kind from commercial_fixtures where kind in ('store','otherstore');
insert into public.eo_store_members(user_id,store_id) select p.id,s.id from commercial_fixtures p cross join commercial_fixtures s where (p.kind in ('person','director') and s.kind='store') or (p.kind='outside' and s.kind='otherstore');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from commercial_fixtures where kind='person'),true);
do $$
declare sid uuid:=(select id from commercial_fixtures where kind='store'); adminid uuid:=(select id from commercial_fixtures where kind='admin'); personid uuid:=(select id from commercial_fixtures where kind='person'); denied boolean; result jsonb;
begin
 if not public.eo_module_allowed('future-module') then raise exception 'FAIL: novo módulo não liberado';end if;
 denied:=false;begin perform public.eo_admin_set_module_access('product','selected','{}');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: gerente configurou módulo';end if;
 perform set_config('request.jwt.claim.sub',adminid::text,true);
 perform public.eo_admin_set_module_access('product','selected','{}');
 if not public.eo_module_allowed('product') then raise exception 'FAIL: admin restrito';end if;
 perform set_config('request.jwt.claim.sub',personid::text,true);
 if public.eo_module_allowed('product') then raise exception 'FAIL: oculto permitido';end if;
 denied:=false;begin perform public.eo_save_product_request(sid,'Pedido não autorizado','{}',gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: bypass direto RPC escrita';end if;
 denied:=false;begin perform public.eo_commercial_page('product',current_date-1,current_date+1);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: bypass direto RPC leitura';end if;
 result:=public.eo_reports_summary(current_date-1,current_date+1);
 if exists(select 1 from jsonb_array_elements(result) x where x->>'id'='product') then raise exception 'FAIL: relatório expôs módulo oculto';end if;
 denied:=false;begin perform public.eo_report_audit_page(current_date-1,current_date+1);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: não admin viu auditoria';end if;
 perform set_config('request.jwt.claim.sub',adminid::text,true);
 perform public.eo_admin_set_module_access('product','selected',array[personid]);
 perform set_config('request.jwt.claim.sub',personid::text,true);
 if not public.eo_module_allowed('product') then raise exception 'FAIL: pessoa selecionada sem acesso';end if;
 perform public.eo_save_product_request(sid,'Pedido autorizado','{}',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',adminid::text,true);
 perform public.eo_admin_set_module_access('product','all');
 perform public.eo_admin_set_module_access('diary','selected','{}');
 perform public.eo_admin_set_module_access('mood','selected','{}');
 perform set_config('request.jwt.claim.sub',personid::text,true);
 result:=public.eo_operational_overview(current_date-1,current_date+1);
 if result->>'diary_count'<>'0' or result->>'mood_count'<>'0' then raise exception 'FAIL: overview expôs módulo oculto';end if;
 perform set_config('request.jwt.claim.sub',adminid::text,true);
 perform public.eo_admin_set_module_access('reports','selected','{}');
 perform set_config('request.jwt.claim.sub',personid::text,true);
 denied:=false;begin perform public.eo_reports_summary(current_date-1,current_date+1);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: central oculta acessível';end if;
end; $$;
reset role;
rollback;
select 'PASSOU: visibilidade, RPCs diretas, administradores e relatórios por origem' as resultado;
